def max_envelopes(envelopes):
    envelopes.sort(key=lambda e: (e[0], -e[1]))          # width asc, height desc for ties
    tails = []
    for _, h in envelopes:
        lo, hi = 0, len(tails)
        while lo < hi:                                     # binary search insertion point
            mid = (lo + hi) // 2
            if tails[mid] < h:
                lo = mid + 1
            else:
                hi = mid
        if lo == len(tails):
            tails.append(h)
        else:
            tails[lo] = h
    return len(tails)

