public class Main {
    static int maxEnvelopes(int[][] envelopes) {
        Arrays.sort(envelopes, (a, b) -> a[0] != b[0] ? a[0] - b[0] : b[1] - a[1]);  // width asc, height desc for ties
        List<Integer> tails = new ArrayList<>();
        for (int[] e : envelopes) {
            int h = e[1];
            int lo = 0, hi = tails.size();
            while (lo < hi) {                                    // binary search insertion point
                int mid = (lo + hi) / 2;
                if (tails.get(mid) < h) lo = mid + 1; else hi = mid;
            }
            if (lo == tails.size()) tails.add(h); else tails.set(lo, h);
        }
        return tails.size();
    }
}

