using namespace std;

int maxEnvelopes(vector<vector<int>>& envelopes) {
    sort(envelopes.begin(), envelopes.end(), [](vector<int>& a, vector<int>& b) {
        return a[0] != b[0] ? a[0] < b[0] : a[1] > b[1];        // width asc, height desc for ties
    });
    vector<int> tails;
    for (auto& e : envelopes) {
        int h = e[1];
        int lo = 0, hi = tails.size();
        while (lo < hi) {                                        // binary search insertion point
            int mid = (lo + hi) / 2;
            if (tails[mid] < h) lo = mid + 1; else hi = mid;
        }
        if (lo == (int)tails.size()) tails.push_back(h);
        else tails[lo] = h;
    }
    return tails.size();
}
